// Interleaved (BIP/BIL) cubes keep a pixel's bands together, so readBand(b) reads the whole image
// area and keeps one band. readBands(first, count) reads it once and returns count bands.
export function interleavedCube(read, header) {
  return {
    bands: header.bands,
    readBand: async (band) => (await read(band, 1))[0],
    readBands: (first, count) => read(first, count),
  };
}

