function summarise(values) {
  let min = Infinity;
  let max = -Infinity;
  let sum = 0;
  for (const v of values) {
    if (v < min) min = v;
    if (v > max) max = v;
    sum += v;
  }
  return { min, max, mean: sum / values.length };
}

// Band statistics of a BIP or BIL cube.
export async function allBandStats(cube) {
  const stats = [];
  for (let band = 0; band < cube.bands; band += 1) {
    const values = await cube.readBand(band);
    stats.push(summarise(values));
  }
  return stats;
}
